        b16 = ""
        for c in enc_text:
            b16 += unshift(c, key)
        try:
            flag = b16_decode(b16)
            print(f"Key: {key}, Flag: {flag}")
        except Exception as e:
            pass
    else:
        print(f"Key: {key}, enc_text has chars not in ALPHABET")
